SELECT id, property_id, property_code, property_name, checkin, checkout, amount FROM dashboard_bookings WHERE UPPER(COALESCE(property_code, '')) = 'GH-KBP' OR UPPER(COALESCE(property_id, '')) LIKE '%GH-KBP%' OR UPPER(COALESCE(property_name, '')) LIKE '%KOTA BARU PARAHYANGAN%';
UPDATE dashboard_bookings SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'DVH'), property_code = 'DVH', property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'DVH') WHERE (UPPER(COALESCE(property_code, '')) = 'GH-KBP' OR UPPER(COALESCE(property_id, '')) LIKE '%GH-KBP%' OR UPPER(COALESCE(property_name, '')) LIKE '%KOTA BARU PARAHYANGAN%') AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'DVH');
SELECT property_id, property_name, kind, COUNT(*) AS jumlah, COALESCE(SUM(amount), 0) AS total FROM finance_entries WHERE UPPER(COALESCE(property_id, '')) LIKE '%GH-KBP%' OR UPPER(COALESCE(property_name, '')) LIKE '%KOTA BARU PARAHYANGAN%' GROUP BY property_id, property_name, kind;
UPDATE finance_entries SET property_id = (SELECT COALESCE(NULLIF(TRIM(dashboard_id), ''), id) FROM properties WHERE UPPER(property_code) = 'DVH'), property_name = (SELECT name FROM properties WHERE UPPER(property_code) = 'DVH') WHERE (UPPER(COALESCE(property_id, '')) LIKE '%GH-KBP%' OR UPPER(COALESCE(property_name, '')) LIKE '%KOTA BARU PARAHYANGAN%') AND EXISTS (SELECT 1 FROM properties WHERE UPPER(property_code) = 'DVH');
DELETE FROM dashboard_bookings WHERE UPPER(COALESCE(property_code, '')) = 'GH-KBP';
DELETE FROM properties WHERE UPPER(property_code) = 'GH-KBP';
SELECT (SELECT COUNT(*) FROM dashboard_bookings WHERE UPPER(property_code) = 'DVH') AS booking_DVH, (SELECT COALESCE(SUM(amount), 0) FROM dashboard_bookings WHERE UPPER(property_code) = 'DVH') AS total_booking_DVH, (SELECT COUNT(*) FROM dashboard_bookings WHERE UPPER(COALESCE(property_code, '')) = 'GH-KBP') AS sisa_booking_GHKBP, (SELECT COUNT(*) FROM properties WHERE UPPER(property_code) = 'GH-KBP') AS sisa_properti_GHKBP;
